declare(strict_types=1);if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/saas/bootstrap.php';require_once __DIR__.'/saas/credits.php';$uid=saas_require_login();$db=saas_db();$u=saas_sync_user_credits($uid);$s=$db->prepare('SELECT name,email,avatar,credits,plan,credit_period_ends_at FROM creator_users WHERE id=? LIMIT 1');$s->execute([$uid]);$user=$s->fetch(PDO::FETCH_ASSOC)?:['name'=>'User','email'=>'','credits'=>0,'plan'=>'free','credit_period_ends_at'=>null];$w=saas_wallet($uid);$plans=$db->query('SELECT * FROM saas_plans WHERE active=1 ORDER BY price_inr')->fetchAll(PDO::FETCH_ASSOC);$code=saas_referral_code($uid);$ref=$db->prepare('SELECT COALESCE(SUM(commission_inr),0) FROM saas_referrals WHERE referrer_id=?');$ref->execute([$uid]);$earned=(float)$ref->fetchColumn();require_once __DIR__.'/header.php';
